def transform(grid):
    h, w = len(grid), len(grid[0])

    # Horizontal bands: infer the repeating row sequence from the
    # nonblank rows and fill blank rows at matching phases.
    if all(len(set(row)) == 1 for row in grid):
        for p in range(1, h + 1):
            phase_values = {}
            consistent = True
            for r, row in enumerate(grid):
                value = row[0]
                if value == 0:
                    continue
                phase = r % p
                if phase in phase_values and phase_values[phase] != value:
                    consistent = False
                    break
                phase_values[phase] = value
            if consistent:
                fallback = next(iter(phase_values.values()), 0)
                return [
                    [phase_values.get(r % p, fallback)] * w
                    for r in range(h)
                ]

    # For diagonal stripe patterns, each diagonal has a repeated color.
    diagonal_values = {}
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value:
                diagonal_values[(c - r) % (h + w)] = value

    for p in range(1, h + w + 1):
        phases = {}
        consistent = True
        for diagonal, value in diagonal_values.items():
            phase = diagonal % p
            if phase in phases and phases[phase] != value:
                consistent = False
                break
            phases[phase] = value
        if consistent and phases:
            fallback = next(iter(phases.values()))
            return [
                [phases.get((c - r) % p, fallback) for c in range(w)]
                for r in range(h)
            ]

    return [list(row) for row in grid]
